		{
			body_v = 0.0;
			body_y = y;
			body_x = 0.0;
			body_xv = 0.0;
			hip_shift = 0.0;
			hip_v = 0.0;
			v_last = NAN;
			air_lean = 0.0;
			air_pull = 0.0;
			_air_pull_v = 0.0;
			a_drive = 0.0;
			pitch_v = 0.0;
			compress_v = 0.0;
			lean_v = 0.0;
			steer_in_v = 0.0;
			air_w = 0.0;
			air_tilt = 0.0;
			air_tilt_v = 0.0;
			flick = 0.0;
			flick_v = 0.0;
			bike_lean = 0.0;
			counter = 0.0;
			man_a = 0.0;
			man_w = 0.0;
			bank = 0.0;
			_bank_hold = 0.0;
			bank_v = 0.0;
			corner_g = 0.0;
			nose_a = 0.0;
			nose_w = 0.0;
			gest_hop = 0.0;
